import 'dart:io';

import 'package:code_builder/code_builder.dart';
import 'package:dart_style/dart_style.dart';

Future<void> main() async {
  const comment = Code(
    '// Generated by `./generate_code.sh`\n'
    '//\n'
    '// DO NOT EDIT MANUALLY\n'
    '//\n',
  );

  final imports = [
    Directive.import('package:meta/meta.dart'),
    Directive.import('package:listen/listen.dart'),
    Directive.import(
      'package:value_listenable_extensions/value_listenable_extensions.dart',
    ),
  ];

  var extensions = <Spec>[];
  for (var i = 2; i <= 20; i++) {
    final valueTypes = <String>[];
    final valueNames = <String>[];
    for (var x = 1; x <= i; x++) {
      valueTypes.add('T$x');
      valueNames.add('v$x');
    }

    final fields = [for (var x = 1; x <= i; x++) '\$$x'].join(',');

    final combineLatestMethod = Method((b) {
      b.annotations.add(const CodeExpression(Code('useResult')));
      b.name = 'combineLatest';

      b.requiredParameters.add(
        Parameter((p) {
          p.name = 'combine';
          p.type = FunctionType((f) {
            f.requiredParameters.addAll([
              for (final (i, type) in valueTypes.indexed)
                refer('$type ${valueNames[i]}'),
            ]);

            f.returnType = refer('U');
          });
        }),
      );
      b.optionalParameters.add(
        Parameter((p) {
          p.name = 'dispose';
          p.type = refer('VoidCallback?');
          p.named = true;
        }),
      );

      b.types.add(refer('U'));

      b.returns = refer('DisposableValueListenable<U>');
      b.body = Code(
        'return combineLatest$i($fields, combine, dispose: dispose,);',
      );
    });

    final combineLatestAsyncMethod = Method((b) {
      b.annotations.add(const CodeExpression(Code('useResult')));
      b.name = 'combineLatestAsync';

      b.requiredParameters.add(
        Parameter((p) {
          p.name = 'combine';
          p.type = FunctionType((f) {
            f.requiredParameters.addAll([
              for (final (i, type) in valueTypes.indexed)
                refer('$type ${valueNames[i]}'),
            ]);

            f.returnType = refer('Future<U>');
          });
        }),
      );
      b.optionalParameters.add(
        Parameter((p) {
          p.name = 'dispose';
          p.type = refer('VoidCallback?');
          p.named = true;
        }),
      );

      b.types.add(refer('U'));

      b.returns = refer('DisposableAsyncValueListenable<U>');
      b.body = Code(
        'return combineLatestAsync$i($fields, combine, dispose: dispose,);',
      );
    });

    extensions.add(
      Extension((b) {
        b.name = 'ValueListenablesCombineLatest$i';
        b.types.addAll(valueTypes.map(refer));
        b.on = refer(
          '(${valueTypes.map((t) => 'ValueListenable<$t>').join(',')})',
        );
        b.methods.addAll([combineLatestMethod, combineLatestAsyncMethod]);
      }),
    );
  }

  final emitter = DartEmitter(orderDirectives: true, useNullSafetySyntax: true);

  final code = <Spec>[
    comment,
    ...imports,
    ...extensions,
  ].map((e) => e.accept(emitter)).join('\n');

  await File('./lib/src/combine_latest_record.dart').writeAsString(
    DartFormatter(
      languageVersion: DartFormatter.latestLanguageVersion,
      pageWidth: 80,
    ).format(code),
  );
}
